package br.com.mecaniQA.api.Repository;
import br.com.mecaniQA.api.model.*; import br.com.mecaniQA.api.Mappers.ItemPedidoResultSetMapper; import br.com.mecaniQA.api.Enums.*; import java.sql.*; import java.util.*; import java.time.*;
public class ItemPedidoRepository extends JdbcSupport implements Repository<ItemPedido,Long>{private static final ItemPedidoRepository INSTANCE=new ItemPedidoRepository();public static ItemPedidoRepository getInstance(){return INSTANCE;}public ItemPedido cadastrar(ItemPedido x){return save(x);}public List<ItemPedido>listarTodos(){return findAll();}public ItemPedido buscarPorId(Long id){return findById(id).orElse(null);}public List<ItemPedido>buscarPorPedidoId(Long id){return query("SELECT * FROM itens_pedido WHERE numero_pedido=?",new ItemPedidoResultSetMapper()::map,id);}public List<ItemPedido>buscarPorPecaId(Long id){return query("SELECT * FROM itens_pedido WHERE codigo_peca=?",new ItemPedidoResultSetMapper()::map,id);}public ItemPedido atualizar(Long id,ItemPedido x){x.setIdItem(id);return update(x);}public ItemPedido atualizarQuantidadeEPreco(Long id,int q,double p){ItemPedido x=buscarPorId(id);if(x==null)return null;x.atualizar(q,p);return update(x);}public ItemPedido deletar(Long id){ItemPedido x=buscarPorId(id);if(x!=null)deleteById(id);return x;}public int getTotalItens(){return findAll().size();}public void limpar(){execute("DELETE FROM itens_pedido");}
 public ItemPedido save(ItemPedido x){long id=insert("INSERT INTO itens_pedido(numero_pedido,codigo_peca,quantidade,preco_unitario,subtotal,observacoes) VALUES(?,?,?,?,?,?)",x.getPedidoPecas().getNumeroPedido(),x.getPeca().getCodigoUnico(),x.getQuantidade(),x.getPrecoUnitario(),x.getSubtotal(),x.getObservacoes());x.setIdItem(id);return x;}public Optional<ItemPedido>findById(Long id){return query("SELECT * FROM itens_pedido WHERE id_item=?",new ItemPedidoResultSetMapper()::map,id).stream().findFirst();}public List<ItemPedido>findAll(){return query("SELECT * FROM itens_pedido ORDER BY id_item",new ItemPedidoResultSetMapper()::map);}public ItemPedido update(ItemPedido x){int n=execute("UPDATE itens_pedido SET numero_pedido=?,codigo_peca=?,quantidade=?,preco_unitario=?,subtotal=?,observacoes=? WHERE id_item=?",x.getPedidoPecas().getNumeroPedido(),x.getPeca().getCodigoUnico(),x.getQuantidade(),x.getPrecoUnitario(),x.getSubtotal(),x.getObservacoes(),x.getIdItem());return n==0?null:x;}public void deleteById(Long id){execute("DELETE FROM itens_pedido WHERE id_item=?",id);}public boolean existsById(Long id){return !query("SELECT id_item FROM itens_pedido WHERE id_item=?",r->r.getLong(1),id).isEmpty();}private ItemPedido map(ResultSet r)throws SQLException{OrdemServico os=OrdemServico.builder().comCliente(new Cliente()).comVeiculo(new Veiculo()).comDescricaoProblema("Pedido carregado do banco").comStatus(StatusOrdemServico.ABERTO).build();PedidoPecas pedido=new PedidoPecas(os,StatusPedidoPecas.ORCANDO);setId(pedido,"numeroPedido",r.getLong("numero_pedido"));Pecas p=new Pecas("Item carregado",null,0,null,0,0,null);setId(p,"codigoUnico",r.getLong("codigo_peca"));ItemPedido x=new ItemPedido(pedido,p,r.getInt("quantidade"),r.getDouble("preco_unitario"));setId(x,"idItem",r.getLong("id_item"));x.setObservacoes(r.getString("observacoes"));return x;}}
